from collections import defaultdict, deque

def lcf_graph(n, lcf_list):
    """Construct graph from LCF notation"""
    edges = set()
    for i in range(n):
        u, v = i, (i+1) % n
        if u > v: u, v = v, u
        edges.add((u, v))
    period = len(lcf_list)
    for i in range(n):
        offset = lcf_list[i % period]
        j = (i + offset) % n
        u, v = min(i, j), max(i, j)
        edges.add((u, v))
    return list(edges)

def check_girth(edges, n):
    adj = defaultdict(set)
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)
    min_cycle = float('inf')
    for start in range(n):
        dist = {start: 0}
        parent = {start: -1}
        queue = deque([start])
        while queue:
            node = queue.popleft()
            for neighbor in adj[node]:
                if neighbor not in dist:
                    dist[neighbor] = dist[node] + 1
                    parent[neighbor] = node
                    queue.append(neighbor)
                elif parent[node] != neighbor:
                    cycle_len = dist[node] + dist[neighbor] + 1
                    min_cycle = min(min_cycle, cycle_len)
    return min_cycle

def check_colorable(edges, n, k):
    adj = defaultdict(set)
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)
    colors = [-1] * n
    def bt(v):
        if v == n:
            return True
        used = {colors[u] for u in adj[v] if colors[u] != -1}
        for c in range(k):
            if c not in used:
                colors[v] = c
                if bt(v + 1):
                    return True
                colors[v] = -1
        return False
    ok = bt(0)
    return ok, colors if ok else None

# McGee graph LCF: [12, 7, -7]^8
mcgee_edges = lcf_graph(24, [12, 7, -7])
print(f"Edges: {len(mcgee_edges)}")
print(f"Girth: {check_girth(mcgee_edges, 24)}")
ok, coloring = check_colorable(mcgee_edges, 24, 5)
print(f"5-colorable: {ok}")
if ok:
    print(f"Coloring: {coloring}")
    print(f"Colors used: {max(coloring)+1}")

print("\nEdge list:")
for e in sorted(mcgee_edges):
    print(e)
